<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { Refresh, TrendCharts, Trophy, CircleCheck, List } from '@element-plus/icons-vue'
import type { StatisticsOverview } from '../../../shared/types'
const data=ref<StatisticsOverview|null>(null),loading=ref(false)
async function load(){loading.value=true;try{data.value=await window.api.statistics.overview()}finally{loading.value=false}}
const maxDaily=computed(()=>Math.max(1,...(data.value?.trends.map(item=>item.success+item.failed)??[1])))
const successLine=computed(()=>points('success')),failedLine=computed(()=>points('failed'))
function points(key:'success'|'failed'){return (data.value?.trends??[]).map((item,index)=>`${index*(680/29)},${120-(item[key]/maxDaily.value)*105}`).join(' ')}
onMounted(load)
</script>
<template><div class="page stats-page" v-loading="loading"><header class="page-header"><div><h1>统计中心</h1><p>依据本地执行记录生成近 30 天签到质量报告。</p></div><el-button :icon="Refresh" @click="load">刷新</el-button></header>
  <template v-if="data"><section class="stat-cards"><div class="panel stat-card"><el-icon><List/></el-icon><div><span>累计执行</span><strong>{{data.totalRuns}}</strong></div></div><div class="panel stat-card success"><el-icon><CircleCheck/></el-icon><div><span>成功执行</span><strong>{{data.successRuns}}</strong></div></div><div class="panel stat-card"><el-icon><TrendCharts/></el-icon><div><span>总体成功率</span><strong>{{data.successRate}}%</strong></div></div><div class="panel stat-card trophy"><el-icon><Trophy/></el-icon><div><span>启用任务</span><strong>{{data.activeTasks}}</strong></div></div></section>
  <section class="panel trend-panel"><div class="chart-head"><div><h3>30 天成功率趋势</h3><p>绿色为成功，红色为失败</p></div></div><div class="line-chart"><svg viewBox="0 0 680 130" preserveAspectRatio="none"><line v-for="y in [15,50,85,120]" :key="y" x1="0" :y1="y" x2="680" :y2="y" stroke="#edf0f5"/><polyline :points="successLine" fill="none" stroke="#2eb486" stroke-width="3" vector-effect="non-scaling-stroke"/><polyline :points="failedLine" fill="none" stroke="#df666a" stroke-width="2" vector-effect="non-scaling-stroke"/></svg><div class="axis"><span>{{data.trends[0]?.date.slice(5)}}</span><span>{{data.trends[14]?.date.slice(5)}}</span><span>{{data.trends[29]?.date.slice(5)}}</span></div></div></section>
  <div class="stats-grid"><section class="panel ranking"><div class="chart-head"><div><h3>连续签到排行</h3><p>当前连续成功天数</p></div></div><div v-if="data.leaderboard.length"><div v-for="(item,index) in data.leaderboard" :key="item.taskId" class="rank-row"><b>{{index+1}}</b><div><strong>{{item.siteName}}</strong><span>{{item.accountLabel||'默认账户'}}</span></div><em>{{item.consecutiveDays}} 天</em></div></div><div v-else class="blank">暂无任务</div></section>
  <section class="panel rates"><div class="chart-head"><div><h3>任务成功率</h3><p>按历史执行记录汇总</p></div></div><div v-if="data.taskRates.length"><div v-for="item in data.taskRates" :key="item.taskId" class="rate-row"><div><strong>{{item.siteName}}</strong><span>{{item.success}} / {{item.total}}</span></div><el-progress :percentage="item.rate" :stroke-width="7"/><b>{{item.rate}}%</b></div></div><div v-else class="blank">执行任务后显示统计</div></section></div></template>
</div></template>
<style scoped>
.stats-page{max-width:1080px}.stat-cards{display:grid;grid-template-columns:repeat(4,1fr);gap:13px;margin-bottom:15px}.stat-card{padding:18px;display:flex;gap:13px;align-items:center}.stat-card>.el-icon{width:38px;height:38px;border-radius:11px;background:#edf2ff;color:#426bd7;font-size:18px}.stat-card.success>.el-icon{background:#e8f7f1;color:#24a779}.stat-card.trophy>.el-icon{background:#fff3e4;color:#db8a28}.stat-card span{display:block;font-size:10px;color:#8995a8}.stat-card strong{display:block;font-size:22px;margin-top:3px}.trend-panel{padding:22px;margin-bottom:15px}.chart-head h3{font-size:14px;margin:0}.chart-head p{font-size:10px;color:#98a2b2;margin:4px 0 0}.line-chart{margin-top:22px;height:175px}.line-chart svg{width:100%;height:140px;overflow:visible}.axis{display:flex;justify-content:space-between;color:#a0a8b5;font-size:9px;margin-top:5px}.stats-grid{display:grid;grid-template-columns:.85fr 1.4fr;gap:15px}.ranking,.rates{padding:21px}.ranking .chart-head,.rates .chart-head{margin-bottom:14px}.rank-row{display:flex;align-items:center;gap:11px;padding:11px 0;border-bottom:1px solid #eff2f5}.rank-row>b{width:24px;height:24px;border-radius:7px;display:grid;place-items:center;background:#f0f3f8;color:#71809a;font-size:10px}.rank-row div{flex:1}.rank-row strong,.rank-row span{display:block}.rank-row strong{font-size:11px}.rank-row span{font-size:9px;color:#9aa3b2;margin-top:3px}.rank-row em{font-style:normal;color:#2b65cd;font-size:11px;font-weight:650}.rate-row{display:grid;grid-template-columns:130px 1fr 38px;gap:12px;align-items:center;padding:11px 0}.rate-row>div strong,.rate-row>div span{display:block}.rate-row>div strong{font-size:10px}.rate-row>div span{font-size:9px;color:#9ba4b2;margin-top:3px}.rate-row>b{font-size:10px;color:#52627a;text-align:right}.blank{height:150px;display:grid;place-items:center;color:#9ea7b5;font-size:11px}
</style>
